<# Generate the T3 support-machine balance table from editable JSON. #>
param([string]$RepoRoot = (Split-Path $PSScriptRoot -Parent), [switch]$Check)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$RepoRoot = [System.IO.Path]::GetFullPath($RepoRoot)
$dataRoot = Join-Path $RepoRoot 'src/main/resources/data/lithmod'
$tier = Get-Content -LiteralPath (Join-Path $dataRoot 'tiers/t3.json') -Raw | ConvertFrom-Json
$lines = @(
    '# T3 balance reference', '',
    'Generated by `tools/generate-t3-slice.ps1`; edit the JSON sources and regenerate.', '',
    ('T3: ' + $tier.display_name + '; ' + $tier.layers + ' layers; ' + $tier.layer_ticks + ' ticks per layer.'), '',
    '| Support recipe / selected design | Input | Secondary | Water (mB) | Output | Ticks | FE/tick | Total FE |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |'
)
foreach ($file in (Get-ChildItem -LiteralPath (Join-Path $dataRoot 'support_recipes') -Filter '*.json' -File | Sort-Object Name)) {
    $r = Get-Content -LiteralPath $file.FullName -Raw | ConvertFrom-Json -AsHashtable
    $secondary = if ($r.Contains('secondary')) { "$($r.secondary.count) x $($r.secondary.item)" } else { '-' }
    $lines += "| $($file.BaseName) | $($r.input.count) x $($r.input.item) | $secondary | $($r.water_mb) | $($r.count) x $($r.output) | $($r.duration) | $($r.energy_per_tick) | $([long]$r.duration * $r.energy_per_tick) |"
}
$lines += @('', 'Both support machines are 2 wide x 2 high x 3 deep. Place one controller in either lower front column, one or two support power ports, and support casings in the other positions. Power enters through a formed owned port.', '', 'Buckets add 1,000 mB at a time. Tanks start empty. The water tank is separate from bucket handling so a future fluid capability can reuse it; pipes are not implemented.', '', 'E-beam design selection maps to the named JSON recipe. Press Write mask to start; completion produces a generation-2 mask. The configured mask-use count and recipe costs are captured when the job starts.', '', 'See [the playable T3 walkthrough](manual-walkthrough-t3.md) and [all recipes](recipes.md).')
$content = ($lines -join "`n") + "`n"
$output = Join-Path $RepoRoot 'docs/t3-slice.md'
if ($Check) {
    if (-not (Test-Path -LiteralPath $output) -or [System.IO.File]::ReadAllText($output) -cne $content) { throw 'docs/t3-slice.md is stale; run tools/generate-t3-slice.ps1.' }
    Write-Host 'T3 reference matches the JSON sources.'
} else {
    [System.IO.File]::WriteAllText($output, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host 'Generated docs/t3-slice.md.'
}
